"""Parser unit tests for each supported format, using synthetically generated bytes
(no fixture files needed)."""

from __future__ import annotations

import io

import docx
from pypdf import PdfWriter

from app.services.parsing import parse_docx, parse_html, parse_markdown, parse_pdf


def test_parse_pdf_preserves_page_numbers() -> None:
    writer = PdfWriter()
    writer.add_blank_page(width=200, height=200)
    writer.add_blank_page(width=200, height=200)
    buf = io.BytesIO()
    writer.write(buf)

    parsed = parse_pdf(buf.getvalue())
    assert parsed.page_count == 2
    # Blank pages extract no text, so sections may be empty - just assert no crash and
    # correct page_count bookkeeping.


def test_parse_docx_tracks_headings_as_section_titles() -> None:
    document = docx.Document()
    document.add_heading("Introduction", level=1)
    document.add_paragraph("This is the intro paragraph with enough words to matter.")
    document.add_heading("Methods", level=1)
    document.add_paragraph("This is the methods paragraph describing the approach used.")
    buf = io.BytesIO()
    document.save(buf)

    parsed = parse_docx(buf.getvalue())
    titles = [s.section_title for s in parsed.sections]
    assert "Introduction" in titles
    assert "Methods" in titles
    intro_section = next(s for s in parsed.sections if s.section_title == "Introduction")
    assert "intro paragraph" in intro_section.text


def test_parse_markdown_headings_and_paragraphs() -> None:
    md_text = (
        "# Title One\n\nSome intro text under title one.\n\n"
        "## Subsection\n\nMore text describing the subsection in detail.\n"
    ).encode("utf-8")

    parsed = parse_markdown(md_text)
    titles = [s.section_title for s in parsed.sections]
    assert "Title One" in titles
    assert "Subsection" in titles


def test_parse_html_headings_and_paragraphs() -> None:
    html = (
        b"<html><body>"
        b"<h1>Chapter One</h1><p>This is the first paragraph of chapter one.</p>"
        b"<h2>Section A</h2><p>This is content inside section A of the document.</p>"
        b"</body></html>"
    )
    parsed = parse_html(html)
    titles = [s.section_title for s in parsed.sections]
    assert "Chapter One" in titles
    assert "Section A" in titles


def test_parse_html_strips_script_and_style() -> None:
    html = (
        b"<html><body><script>alert('x')</script><style>.a{}</style>"
        b"<p>Visible paragraph text only.</p></body></html>"
    )
    parsed = parse_html(html)
    combined = " ".join(s.text for s in parsed.sections)
    assert "alert" not in combined
    assert "Visible paragraph text only." in combined
